?>
<div class="sl-head"><div><h1 class="sl-title row g8"><span class="sl-tile" style="background:var(--ink);color:var(--inverse)"><i class="ic i-ai" aria-hidden="true"></i></span>Profile studio</h1><p class="sl-lede">Change your photo, fix your name and pick your icon. Changes show on your account, receipts and labels.</p></div><div class="row g8"><?php if ($avatar): ?><button class="sl-btn ghost" type="button" data-sl-action="<?= $ep ?>" data-p-op="reset_photo" data-sl-confirm="Remove your photo and show your initials instead?"><i class="ic ic-sm i-refresh" aria-hidden="true"></i>Reset photo</button><?php endif; ?><button class="sl-btn" type="submit" form="st-name"><i class="ic ic-sm i-check" aria-hidden="true"></i>Save changes</button></div></div>
<?php if (sl_get($d, 'isAdmin')): ?>
<section class="sl-card col g12 bk" id="retouch-all"><div class="sl-ch" style="margin:0"><div><h2 class="sl-ct row g8"><i class="ic i-wand" aria-hidden="true"></i>Retouch all profile photos</h2><span class="mut sm">One command for every photo uploaded to profiles.</span></div><span class="sl-pill sorting">Admins only</span></div>
<div class="sl-banner info"><i class="ic ic-sm i-info" aria-hidden="true"></i><span>Not available yet: the AI assistant set up in AI Centre <?= sl_get($d, 'aiOn') ? 'answers questions but cannot edit images' : 'is not configured' ?>. Bulk retouching needs an image-editing provider.</span></div>
<div class="row g8"><button class="sl-btn" style="height:46px" type="button" disabled aria-disabled="true"><i class="ic ic-sm i-wand" aria-hidden="true"></i>Retouch all photos</button></div></section>
<?php endif; ?>
<div class="split">
<section class="a sl-card col g16" id="retouch"><div class="sl-ch" style="margin:0"><h2 class="sl-ct">Your photo</h2><div class="sl-seg boxed"><button type="button" class="on">Original</button><button type="button" disabled title="Needs an AI image provider">AI retouched</button></div></div>
<div class="row g24 wrap top"><div class="st-ph"><div class="bgl" style="background:#C9C3B6"></div><div class="img" id="st-img" style="<?= $avatar ? 'background-image:url(' . h($avatar) . ');background-size:cover;background-position:center' : '' ?>"><?php if (!$avatar): ?><span style="display:grid;place-items:center;width:100%;height:100%;font-size:64px;font-weight:500;color:var(--ink)"><?= sl_v($d, 'ini') ?></span><?php endif; ?></div><span class="tag"><?= $avatar ? 'Original' : 'Initials' ?></span></div>
<div class="col g12 grow" style="min-width:260px"><?php foreach ($tools as $t): ?><button class="st-tool" type="button" disabled aria-disabled="true" style="opacity:.55;cursor:not-allowed"><span class="sl-tile"><i class="ic <?= h($t[0]) ?>" aria-hidden="true"></i></span><span class="col grow"><b class="fw5"><?= h($t[1]) ?></b><span class="mut sm"><?= h($t[2]) ?></span></span><i class="ic ic-sm i-lock" aria-hidden="true"></i></button><?php endforeach; ?>
<span class="mut sm" id="reset">AI retouching is switched off: it needs an image-editing AI provider<?= sl_get($d, 'aiOn') ? ' (the configured assistant is text only)' : '' ?>. You can still upload a new photo.</span>
