<aside class="b col g16">
<form class="sl-card col g12" id="st-name" data-sl-form action="<?= $ep ?>"><input type="hidden" name="op" value="profile"><h2 class="sl-ct" id="name">Your name</h2>
<div class="grid cols2" style="gap:10px"><label class="sl-field"><span class="sl-lab">First name</span><input class="sl-in" name="fname" value="<?= sl_v($d, 'fname') ?>" required maxlength="60" autocomplete="given-name"></label><label class="sl-field"><span class="sl-lab">Last name</span><input class="sl-in" name="lname" value="<?= sl_v($d, 'lname') ?>" required maxlength="60" autocomplete="family-name"></label></div>
<?php if (sl_get($d, 'suggest') !== sl_get($d, 'name')): ?><div class="row g8" style="padding:10px 12px;border-radius:12px;background:var(--active)"><i class="ic ic-sm i-spark" aria-hidden="true"></i><span class="grow sm">Suggestion: <b class="fw5"><?= sl_v($d, 'suggest') ?></b></span><button class="sl-btn sm" type="button" id="st-use" data-name="<?= sl_v($d, 'suggest') ?>">Use</button></div><?php endif; ?>
<?php if (sl_get($d, 'canEditPhone')): ?><label class="sl-field"><span class="sl-lab">Phone</span><input class="sl-in mono" name="phone" value="<?= sl_v($d, 'phone') ?>" inputmode="tel" autocomplete="tel"></label><?php else: ?><div class="mut sm">To change your WhatsApp number, use <a href="<?= h(sl_route('UserHome', ['edit' => 1])) ?>">My profile</a> (we confirm it with a code).</div><?php endif; ?>
<div class="mut sm">Must match your ID for customs. Shown on labels as <?= sl_v($d, 'labelName') ?>.</div></form>
<section class="sl-card col g12" id="icon"><h2 class="sl-ct">Your icon</h2><div class="row g12 wrap"><?php foreach ((array) sl_get($d, 'icons', []) as $i): ?><button class="st-av <?= sl_v($i, 'cls') ?>" type="button" style="<?= sl_v($i, 'sty') ?>" aria-label="<?= sl_v($i, 'label') ?>" data-sl-action="<?= $ep ?>" data-p-op="icon" data-p-style="<?= sl_v($i, 'key') ?>"><?= sl_v($i, 'txt') ?></button><?php endforeach; ?></div><span class="mut sm"><?= sl_v($d, 'iconLabel') ?> · used in the top bar, chat and receipts</span>
<button class="sl-btn ghost sm" type="button" disabled style="align-self:flex-start" title="Needs an AI image provider"><i class="ic ic-sm i-wand" aria-hidden="true"></i>Make new icons with AI</button></section>
<section class="sl-card col g8"><h2 class="sl-ct">Preview</h2><div class="row g12"><span class="st-av on" style="<?= sl_v($d, 'curIconSty') ?>;width:44px;height:44px;font-size:15px"><?= sl_v($d, 'curIconTxt') ?></span><div><div class="fw5"><?= sl_v($d, 'name') ?></div><div class="mut sm"><?= sl_v($d, 'sub') ?></div></div></div></section></aside></div>
